"""
Improvement Engine Models & Builders — ImprovementTask, ImprovementRecommendation, and task builders.
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)


@dataclass
class ImprovementTask:
    """An improvement task generated by the engine."""

    id: str
    title: str
    description: str
    priority: str  # CRITICAL, HIGH, MEDIUM, LOW
    category: str  # reliability, performance, security, tech_debt
    source_analysis: str
    created_at: str = field(default_factory=lambda: datetime.now().isoformat())
    status: str = "pending"  # pending, in_progress, completed, cancelled
    metadata: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        """Convert to dictionary for JSON serialization."""
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description,
            "priority": self.priority,
            "category": self.category,
            "source_analysis": self.source_analysis,
            "created_at": self.created_at,
            "status": self.status,
            "metadata": self.metadata,
        }


@dataclass
class ImprovementRecommendation:
    """A recommendation for improvement."""

    category: str
    description: str
    impact: str  # high, medium, low
    effort: str  # low, medium, high
    details: dict[str, Any] = field(default_factory=dict)


def load_improvements_from_file(improvements_file: Path) -> list[ImprovementTask]:
    """Load improvement tasks from JSON file."""
    if not improvements_file.exists():
        return []

    improvements: list[ImprovementTask] = []
    try:
        data = json.loads(improvements_file.read_text())
        for imp_data in data.get("improvements", []):
            improvement = ImprovementTask(
                id=imp_data["id"],
                title=imp_data["title"],
                description=imp_data["description"],
                priority=imp_data["priority"],
                category=imp_data["category"],
                source_analysis=imp_data["source_analysis"],
                created_at=imp_data.get("created_at", ""),
                status=imp_data.get("status", "pending"),
                metadata=imp_data.get("metadata", {}),
            )
            improvements.append(improvement)
        logger.info(f"[ImprovementEngine] Loaded {len(improvements)} improvements")
    except (json.JSONDecodeError, KeyError) as e:
        logger.warning(f"[ImprovementEngine] Failed to load improvements: {e}")

    return improvements


def build_failure_improvement_task(
    category: str,
    failure_count: int,
    common_errors: list[str],
) -> ImprovementTask:
    """Build an improvement task for a recurring failure category."""
    if failure_count >= 10:
        priority = "CRITICAL"
    elif failure_count >= 5:
        priority = "HIGH"
    elif failure_count >= 3:
        priority = "MEDIUM"
    else:
        priority = "LOW"

    task_id = f"improve-{category}-{datetime.now().strftime('%Y%m%d')}"
    error_lines = "\n".join(f"- {e}" for e in common_errors[:5])
    description = (
        f"Address recurring failures in {category} category.\n\n"
        f"Failure count: {failure_count}\n\n"
        f"Common errors:\n{error_lines}\n\n"
        "Recommended actions:\n"
        "1. Review error patterns and root causes\n"
        "2. Implement fixes or workarounds\n"
        "3. Add tests to prevent regression\n"
        "4. Update documentation if needed"
    )

    return ImprovementTask(
        id=task_id,
        title=f"Fix recurring {category} failures",
        description=description,
        priority=priority,
        category="reliability",
        source_analysis=f"failure_pattern_analysis:{failure_count}_failures",
        metadata={"failure_count": failure_count, "common_errors": common_errors},
    )


def build_tech_debt_task(missions: list[dict[str, Any]]) -> ImprovementTask | None:
    """Analyze missions for tech debt indicators and build a task if threshold met."""
    tech_debt_indicators = ["TODO", "FIXME", "hack", "temporary", "workaround"]
    tech_debt_count = sum(
        1
        for m in missions
        if any(ind in m.get("description", "").lower() for ind in tech_debt_indicators)
    )

    if tech_debt_count < 5:
        return None

    description = (
        "Address accumulated technical debt.\n\n"
        f"Tech debt indicators found in {tech_debt_count} recent missions.\n\n"
        "Recommended actions:\n"
        "1. Review and prioritize TODO/FIXME comments\n"
        "2. Refactor temporary solutions\n"
        "3. Remove workaround code\n"
        "4. Update documentation"
    )
    return ImprovementTask(
        id=f"tech-debt-{datetime.now().strftime('%Y%m%d')}",
        title="Reduce technical debt",
        description=description,
        priority="MEDIUM",
        category="tech_debt",
        source_analysis=f"tech_debt_analysis:{tech_debt_count}_indicators",
        metadata={"tech_debt_count": tech_debt_count},
    )
